'use client';
import { useEffect, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import { spring, springToLinear, useInView, useStudioMotion } from '../../../motion';
import { StudioCanvas } from '../../../three';
import { resolveParams, type EffectMeta, type ParamValues } from '../../../types';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import { Poster } from './Poster';
import { LOOK_MAX, Scene, type Bridge, type Input } from './Scene';
import { VIEWPOINTS, type StopId } from './terrain';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Every recipe param from its meta (defaults), then this demo's overrides. */
const recipe = <T,>(m: EffectMeta, overrides: ParamValues = {}): T => resolveParams(m.params, overrides) as unknown as T;

const CHAPTERS = [
  { id: 'lake', label: 'Lake', time: '21:30', title: 'Lake Kelda at dusk', body: 'We meet at the boathouse while the ridge is still a silhouette. Twenty minutes to let your eyes adjust; head torches stay on red from here on.', meta: 'Start · the lake shore' },
  { id: 'ridge', label: 'Ridge', time: '22:10', title: 'The ridge path', body: 'Two hours on a marked path that never leaves the crest. The contour lines below you are the only map you need, and the guide carries the paper one anyway.', meta: 'About 6 km there and back' },
  { id: 'sky', label: 'Sky', time: '23:40', title: 'Under the northern sky', body: 'On some clear winter nights the sky over the ridge moves. We can’t promise it, and we never charge extra for it. The stars are reliable.', meta: 'Turning point · the summit cairn' },
] as const satisfies readonly { id: StopId; label: string; time: string; title: string; body: string; meta: string }[];

const WALKS = [
  ['Fri 4 Dec 2026', '20:30', '3 h 30', '12'],
  ['Sat 19 Dec 2026', '20:00', '4 h', '12'],
  ['Fri 15 Jan 2027', '20:30', '3 h 30', '10'],
  ['Sat 13 Feb 2027', '21:00', '4 h', '12'],
] as const;

/** Rest zones: the camera holds at each chapter's stop while its caption crosses the middle of the screen. */
const HOLD = 0.05;
function toU(p: number, c: readonly number[]): number {
  if (c.length < 4) return p;
  for (let k = 0; k < 3; k++) {
    const a = c[k] + HOLD;
    const b = c[k + 1] - HOLD;
    if (p <= a) return k / 3;
    if (p < b) { const f = (p - a) / (b - a); return (k + f * f * (3 - 2 * f)) / 3; }
  }
  return 1;
}

/** Drag sensitivity: a drag across 40 % of the stage turns the view by the full ±20°. */
const DRAG_SPAN = 0.4;
/** Past the limit the view still follows the hand, at a third of the rate (rubber band). */
const band = (yaw: number): number => (Math.abs(yaw) <= LOOK_MAX ? yaw : Math.sign(yaw) * (LOOK_MAX + (Math.abs(yaw) - LOOK_MAX) * 0.33));
/** Look buttons: the press kicks the view (rad/s) so even a tap glances; holding keeps it turned. */
const KICK = 1.9;

function WalksTitle() {
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref, { amount: 0.6 });
  const { reduced } = useStudioMotion();
  const text = 'Four walks this winter.';
  return (
    <div ref={ref} className={s.walksTitle}>
      {near || reduced ? <SplitLineReveal params={recipe(splitMeta, { text, stagger: 60, duration: 820, rise: 112, skew: false })} /> : <h2 className={s.placeholder}>{text}</h2>}
    </div>
  );
}

export default function Immersive3DHero() {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const journey = useRef<HTMLDivElement>(null);
  const stage = useRef<HTMLDivElement>(null);
  const hero = useRef<HTMLElement>(null);
  const bridge = useRef<Bridge>({ u: 0, kick: 0, invalidate: null, light: null, sway: null }).current;
  const input = useRef<Input>({ px: 0, py: 0, over: false, drag: 0, dragging: false, release: 0, hold: 0, impulse: 0, yaw: 0 }).current;
  const live = useRef<{ st: ScrollTrigger; centers: () => readonly number[] } | null>(null);
  const [playing, setPlaying] = useState(true);
  const [off3d, setOff3d] = useState(false);
  const [lit3d, setLit3d] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [active, setActive] = useState(0);
  const [stop, setStop] = useState<StopId>('lake');
  const animate = playing && !reduced;
  const release = useMemo(() => springToLinear(spring.press), []);

  // Scene → DOM: the sky light tints the panels' top edges; the camera sway moves the layered title in depth.
  useEffect(() => {
    const j = journey.current;
    const h = hero.current;
    bridge.light = (lit) => j?.style.setProperty('--kr-lit', lit.toFixed(2));
    bridge.sway = (x, y) => { h?.style.setProperty('--kr-sx', x.toFixed(3)); h?.style.setProperty('--kr-sy', y.toFixed(3)); };
    return () => { bridge.light = null; bridge.sway = null; };
  }, [bridge]);

  useGSAP(() => {
    const el = root.current;
    const j = journey.current;
    if (reduced || !el || !j) return;
    const slides = gsap.utils.toArray<HTMLElement>('[data-slide]', j);
    let centers: number[] = [];
    const measure = (self: ScrollTrigger) => {
      const span = Math.max(1, self.end - self.start);
      const mid = 44 + (window.innerHeight - 44) / 2;
      centers = slides.map((x) => {
        const r = x.getBoundingClientRect();
        return gsap.utils.clamp(0, 1, (r.top + window.scrollY + r.height / 2 - mid - self.start) / span);
      });
    };
    const update = (self: ScrollTrigger) => {
      bridge.u = toU(self.progress, centers);
      // Scroll speed → a brief aurora flare: 700 px/s starts it, 4,200 px/s is the full flare.
      const v = Math.abs(self.getVelocity());
      bridge.kick = Math.max(bridge.kick, gsap.utils.clamp(0, 1, (v - 700) / 3500));
      bridge.invalidate?.();
      let best = 0;
      centers.forEach((c, i) => { if (Math.abs(c - self.progress) < Math.abs(centers[best] - self.progress)) best = i; });
      setActive((prev) => (prev === best ? prev : best));
    };
    const st = ScrollTrigger.create({ trigger: j, start: 'top top+=44', end: 'bottom bottom', onRefresh: (self) => { measure(self); update(self); bridge.kick = 0; }, onUpdate: update });
    measure(st);
    update(st);
    bridge.kick = 0;
    live.current = { st, centers: () => centers };

    // Layered type: the three title layers drift apart at different depths as the hero leaves.
    gsap.to(gsap.utils.toArray<HTMLElement>('[data-depth]', j), {
      yPercent: (i: number) => [-90, -48, -20][i] ?? 0,
      ease: 'none',
      scrollTrigger: { trigger: slides[0], start: 'top top+=44', end: 'bottom top+=44', scrub: true },
    });

    let width = el.clientWidth;
    let timer = 0;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      window.clearTimeout(timer);
      timer = window.setTimeout(() => ScrollTrigger.refresh(), 140);
    });
    ro.observe(el);
    let alive = true;
    void document.fonts?.ready.then(() => { if (alive) ScrollTrigger.refresh(); });
    return () => { alive = false; ro.disconnect(); window.clearTimeout(timer); live.current = null; };
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  // Hands on the scene. The canvas never takes pointer events: these listeners sit on the journey, are passive for
  // scrolling (touch-action: pan-y keeps vertical swipes native; the wheel is never touched) and only claim a
  // pointer once a drag is clearly horizontal.
  useEffect(() => {
    const el = journey.current;
    const box = stage.current;
    if (!el || !box) return;
    const g = { id: -1, pending: false, x0: 0, y0: 0, base: 0, samples: [] as { t: number; yaw: number }[] };
    const place = (e: PointerEvent) => {
      const r = box.getBoundingClientRect();
      input.px = ((e.clientX - r.left) / Math.max(1, r.width)) * 2 - 1;
      input.py = -(((e.clientY - r.top) / Math.max(1, r.height)) * 2 - 1);
    };
    const end = (e: PointerEvent) => {
      if (e.pointerId !== g.id) return;
      if (input.dragging) {
        const now = performance.now();
        const old = g.samples.find((p) => now - p.t <= 90) ?? g.samples[0];
        const last = g.samples[g.samples.length - 1];
        const dt = last && old ? (last.t - old.t) / 1000 : 0;
        input.release = dt > 0.008 ? gsap.utils.clamp(-5, 5, (last.yaw - old.yaw) / dt) : 0;
        input.dragging = false;
        setDragging(false);
      }
      if (e.pointerType === 'touch') input.over = false;
      g.id = -1;
      g.pending = false;
      bridge.invalidate?.();
    };
    const onDown = (e: PointerEvent) => {
      if (reduced || e.button !== 0 || g.id !== -1) return;
      const t = e.target as Element | null;
      // Controls, links and the caption panels stay ordinary; for a mouse the title text stays selectable too.
      if (!t || t.closest('button, a, input, [data-caption]') || (e.pointerType === 'mouse' && t.closest('[data-depth]'))) return;
      g.id = e.pointerId;
      g.pending = true;
      g.x0 = e.clientX;
      g.y0 = e.clientY;
      g.base = input.yaw;
      g.samples = [];
      if (e.pointerType === 'mouse') e.preventDefault();
    };
    const onMove = (e: PointerEvent) => {
      if (e.pointerType === 'touch' && e.pointerId !== g.id) return;
      place(e);
      input.over = true;
      if (e.pointerId === g.id) {
        const dx = e.clientX - g.x0;
        const dy = e.clientY - g.y0;
        if (g.pending && Math.abs(dx) > 6 && Math.abs(dx) > Math.abs(dy) * 1.2) {
          g.pending = false;
          input.dragging = true;
          setDragging(true);
          try { el.setPointerCapture(e.pointerId); } catch { /* pointer already gone */ }
        }
        if (input.dragging) {
          const w = Math.max(1, box.clientWidth) * DRAG_SPAN;
          input.drag = band(g.base + (dx / w) * LOOK_MAX);
          const now = performance.now();
          g.samples.push({ t: now, yaw: input.drag });
          while (g.samples.length > 2 && now - g.samples[0].t > 120) g.samples.shift();
        }
      }
      bridge.invalidate?.();
    };
    const onLeave = (e: PointerEvent) => { if (e.pointerId !== g.id) { input.over = false; bridge.invalidate?.(); } };
    // Touch pointers are implicitly captured by the element under the finger; moving the capture to the journey makes
    // that child lose it (the event bubbles here). Only the journey losing its own capture ends a drag.
    const onLost = (e: PointerEvent) => { if (e.target === el) end(e); };
    el.addEventListener('pointerdown', onDown);
    el.addEventListener('pointermove', onMove, { passive: true });
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
    el.addEventListener('lostpointercapture', onLost);
    el.addEventListener('pointerleave', onLeave);
    return () => {
      el.removeEventListener('pointerdown', onDown);
      el.removeEventListener('pointermove', onMove);
      el.removeEventListener('pointerup', end);
      el.removeEventListener('pointercancel', end);
      el.removeEventListener('lostpointercapture', onLost);
      el.removeEventListener('pointerleave', onLeave);
      input.dragging = false;
      input.over = false;
      input.hold = 0;
    };
  }, [bridge, input, reduced]);

  // The keyboard and button twin of the drag: press to glance, hold to keep looking; the view springs back on release.
  const lookProps = (dir: 1 | -1) => {
    const press = () => { input.hold = dir; input.impulse += dir * KICK; bridge.invalidate?.(); };
    const lift = () => { if (input.hold === dir) { input.hold = 0; bridge.invalidate?.(); } };
    return {
      onPointerDown: (e: ReactPointerEvent<HTMLButtonElement>) => { if (e.button === 0) press(); },
      onPointerUp: lift,
      onPointerLeave: lift,
      onPointerCancel: lift,
      onKeyDown: (e: KeyboardEvent<HTMLButtonElement>) => { if ((e.key === ' ' || e.key === 'Enter') && !e.repeat) press(); },
      onKeyUp: (e: KeyboardEvent<HTMLButtonElement>) => { if (e.key === ' ' || e.key === 'Enter') lift(); },
      onBlur: lift,
    };
  };

  const goTo = (i: number): void => {
    if (reduced) { setStop(CHAPTERS[i].id); setActive(i + 1); return; }
    const l = live.current;
    const c = l?.centers()[i + 1];
    if (!l || c === undefined) return;
    window.scrollTo({ top: l.st.start + c * (l.st.end - l.st.start), behavior: 'smooth' });
  };
  const current = reduced ? CHAPTERS.findIndex((c) => c.id === stop) + 1 : active;
  const rootStyle = { '--kr-release': release.easing, '--kr-release-dur': `${release.duration}ms` } as CSSProperties;

  return (
    <div ref={root} className={s.root} data-mode={reduced ? 'static' : 'scroll'} style={rootStyle}>
      <div ref={journey} className={s.journey} data-dragging={dragging || undefined}>
        <div ref={stage} className={s.stage}>
          <Poster />
          <StudioCanvas
            className={s.canvas}
            label="Kelda Ridge at night, drawn as contour lines"
            description="A 3D landscape drawn as contour lines: a lake in the foreground at dusk, a long ridge with the walking route marked in red, stars coming out, and curtains of aurora light over the northern sky. Scrolling moves the camera from the lake, along the ridge and up to the sky; the viewpoint buttons do the same. Moving the pointer aims a warm head-torch at the ground; dragging sideways or the Look buttons turn the view."
            frameloop={animate ? 'always' : 'demand'}
            disabled={off3d}
            flat
            camera={{ fov: 42, near: 0.1, far: 500, position: [...VIEWPOINTS[0].position] }}
            style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}
            onCreated={() => setLit3d(true)}
            data-live={lit3d || undefined}
            fallback={
              <div className={s.fallback}>
                <Poster />
                <p className={s.fallbackNote}>A still drawing of the ridge at dusk. Every chapter below reads the same without the live scene.</p>
              </div>
            }
          >
            <Scene bridge={bridge} input={input} reduced={reduced} animate={animate} stop={stop} />
          </StudioCanvas>
          <div className={s.scrim} aria-hidden="true" />
        </div>

        <div className={s.slides}>
          <header ref={hero} className={s.heroSlide} data-slide="">
            <p className={s.kicker}>Kelda Ridge Night Walks <span aria-hidden="true">·</span> winter season <span aria-hidden="true">·</span> sample site</p>
            <h2 className={s.title}><span className={s.t1} data-depth="">Kelda</span> <span className={s.t2} data-depth="">Ridge</span></h2>
            <p className={s.lede} data-depth="">Up here the dark has detail. Guided night walks above the treeline, from dusk until the sky does what it does.</p>
            {!reduced ? <p className={s.hint} aria-hidden="true"><span>Scroll to walk the ridge ↓</span><span className={s.hintDrag}>Drag to look around ↔</span></p> : null}
          </header>
          {CHAPTERS.map((c, i) => (
            <article key={c.id} className={s.slide} data-slide="" data-side={i % 2 ? 'end' : 'start'} aria-labelledby={`kr-${c.id}`}>
              <div className={s.cap} data-caption="">
                <p className={s.capIdx}><span>{String(i + 1).padStart(2, '0')} / 03</span><span>{c.time}</span></p>
                <h3 id={`kr-${c.id}`} className={s.capTitle}>{c.title}</h3>
                <p className={s.capBody}>{c.body}</p>
                <p className={s.capMeta}>{c.meta}</p>
              </div>
            </article>
          ))}
        </div>

        <div className={s.hud}>
          <nav className={s.views} aria-label="Viewpoints">
            {CHAPTERS.map((c, i) => (
              <button key={c.id} type="button" className={s.view} aria-current={current === i + 1 ? 'step' : undefined} onClick={() => goTo(i)}>
                <span className={s.viewNum} aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>{c.label}
              </button>
            ))}
          </nav>
          <div className={s.ctl}>
            {!reduced ? (
              <div className={s.look} role="group" aria-label="Look around">
                <button type="button" className={s.lookBtn} aria-label="Look left" {...lookProps(1)}>
                  <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" focusable="false"><path d="M10 3L5 8l5 5" /></svg>
                </button>
                <span className={s.lookLabel} aria-hidden="true">Look</span>
                <button type="button" className={s.lookBtn} aria-label="Look right" {...lookProps(-1)}>
                  <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" focusable="false"><path d="M6 3l5 5-5 5" /></svg>
                </button>
              </div>
            ) : null}
            <div className={s.toggles}>
              {!reduced ? <button type="button" className={`${s.toggle} ${s.pauseSky}`} aria-pressed={!playing} onClick={() => setPlaying((p) => !p)}>Pause sky</button> : null}
              <button type="button" className={s.toggle} aria-pressed={off3d} onClick={() => setOff3d((o) => !o)}>Turn off 3D</button>
            </div>
          </div>
        </div>
      </div>

      <section className={s.walks} aria-labelledby="kr-walks-cap">
        <p className={s.kicker}>Winter season</p>
        <WalksTitle />
        <div className={s.tableWrap}>
          <table className={s.table}>
            <caption id="kr-walks-cap" className={s.tableCap}>Sample schedule — fictional dates and places, not bookable</caption>
            <thead><tr><th scope="col">Date</th><th scope="col">Meet</th><th scope="col">Length</th><th scope="col">Places</th></tr></thead>
            <tbody>{WALKS.map((w) => <tr key={w[0]}>{w.map((cell, i) => (i === 0 ? <th key={i} scope="row">{cell}</th> : <td key={i}>{cell}</td>))}</tr>)}</tbody>
          </table>
        </div>
      </section>

      <section className={s.bring} aria-labelledby="kr-bring">
        <h2 id="kr-bring" className={s.h2}>What to bring</h2>
        <ol className={s.bringList}>
          <li>Warm layers and a hat, even when the valley feels mild.</li>
          <li>Boots with ankle support: the path is stony near the top.</li>
          <li>A head torch with a red setting. We can lend one.</li>
          <li>Something hot to drink at the summit cairn.</li>
        </ol>
      </section>

      <section className={s.ask} aria-labelledby="kr-ask">
        <h2 id="kr-ask" className={s.askTitle}>Ask about a place on the ridge.</h2>
        <a className={s.cta} href="mailto:walks@keldaridge.example?subject=Night%20walk">Write to the guides</a>
        <p className={s.fine}>Kelda Ridge Night Walks is fictional; the schedule and places are sample data. The landscape is procedural, drawn from a seeded height field.</p>
      </section>
    </div>
  );
}

/**
 * Kelda Ridge's night is an image, not a theme: the journey is staged at dusk → night in both gallery themes, so the
 * aurora always reads. These are the scene's "film stock" colours, shared by the live scene and the SVG poster. DOM
 * text over the stage uses the night tokens in styles.module.css (contrast checked against the brightest sky).
 */
export const NIGHT = {
  /** Sky at dusk (hero, lake) and at full night (ridge, sky); the afterglow sits on the north-west horizon. */
  duskTop: '#121c36',
  duskHorizon: '#33304c',
  afterglow: '#9c5038',
  nightTop: '#02040a',
  nightHorizon: '#0a111f',
  /** Aurora: oxygen green at the lower edge, violet tops, a rose fringe where the curtain folds. */
  aurGreen: '#47f59b',
  aurViolet: '#7a46d8',
  aurRose: '#ff5c8a',
  /** Ground drawn as contours: index lines pale, minor lines cool grey, the lake darker than the land. */
  groundDusk: '#0d1323',
  groundNight: '#060910',
  line: '#3a4964',
  index: '#9db0d0',
  water: '#03060c',
  /** The walking route and cairns (red head-torch light) and the warm beam of the torch itself. */
  route: '#ff5a2b',
  torch: '#ffb26b',
  star: '#e6edf8',
} as const;

/** Where each named stop sits on the camera path (0–1): drives the colour script when the camera cuts. */
export const STOP_U = { overview: 0, lake: 1 / 3, ridge: 2 / 3, sky: 1 } as const;

'use client';
import { useId, useMemo } from 'react';
import { NIGHT } from './palette';
import s from './styles.module.css';

const r1 = (n: number): number => Math.round(n * 10) / 10;

/**
 * Ridgeline print of Kelda Ridge at dusk, in the scene's own night palette: stacked contour silhouettes, the route,
 * the afterglow and the first aurora curtains, stars. Paints with the page (first paint), stays under the canvas, and
 * is the whole picture without WebGL or with 3D turned off.
 */
export function Poster({ className }: { className?: string }) {
  const id = useId();
  const art = useMemo(() => {
    const shape = (x: number, k: number) =>
      260 * Math.exp(-(((x - 980 - k * 6) / 360) ** 2)) + 150 * Math.exp(-(((x - 430 + k * 4) / 250) ** 2)) + 22 * Math.sin(x / 61 + k * 0.9) + 12 * Math.sin(x / 23 - k);
    const ridges = Array.from({ length: 15 }, (_, k) => {
      const base = 540 + k * 34;
      const amp = 0.55 + k * 0.035;
      const pts: string[] = [];
      for (let x = -20; x <= 1620; x += 20) pts.push(`${x} ${r1(base - shape(x, k) * amp)}`);
      return { d: `M${pts.join('L')}L1620 1020L-20 1020Z`, index: k % 5 === 4, k };
    });
    const route: string[] = [];
    for (let x = 300; x <= 1340; x += 20) route.push(`${x} ${r1(540 + 9 * 34 - shape(x, 9) * (0.55 + 9 * 0.035) - 10)}`);
    let h = 9;
    const rnd = () => { h = (Math.imul(h, 1664525) + 1013904223) >>> 0; return h / 4294967296; };
    const stars = Array.from({ length: 170 }, () => ({ x: r1(rnd() * 1600), y: r1(rnd() * 420), r: r1(0.7 + rnd() * 1.6), o: r1(0.25 + rnd() * 0.7) }));
    // Curtains: a ribbon with a wandering lower edge; rays rise from it.
    const curtains = [0, 1].map((b) => {
      const top: string[] = [];
      const bottom: string[] = [];
      const rays: string[] = [];
      for (let x = 260 + b * 180; x <= 1520 - b * 120; x += 14) {
        const w = Math.sin(((x - 260) / 1260) * Math.PI);
        const y = 250 + b * 64 + 34 * Math.sin(x / 150 + b * 2) + 14 * Math.sin(x / 41 - b);
        bottom.unshift(`${x} ${r1(y)}`);
        top.push(`${x} ${r1(y - (110 + 50 * Math.sin(x / 90 + b)) * w)}`);
        if (rnd() < 0.42) rays.push(`M${r1(x + rnd() * 10)} ${r1(y)}V${r1(y - (40 + 150 * rnd()) * w)}`);
      }
      return { d: `M${top.join('L')}L${bottom.join('L')}Z`, rays: rays.join('') };
    });
    return { ridges, route: `M${route.join('L')}`, stars, curtains };
  }, []);

  return (
    <svg className={`${s.poster} ${className ?? ''}`} viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={`${id}sky`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" stopColor={NIGHT.duskTop} />
          <stop offset="0.5" stopColor={NIGHT.duskHorizon} />
        </linearGradient>
        <radialGradient id={`${id}glow`} cx="0.3" cy="0.52" r="0.55" gradientTransform="translate(0.3 0.52) scale(1 0.32) translate(-0.3 -0.52)">
          <stop offset="0" stopColor={NIGHT.afterglow} stopOpacity="0.85" />
          <stop offset="1" stopColor={NIGHT.afterglow} stopOpacity="0" />
        </radialGradient>
        <filter id={`${id}soft`} x="-10%" y="-20%" width="120%" height="140%"><feGaussianBlur stdDeviation="5" /></filter>
        <filter id={`${id}rays`} x="-10%" y="-20%" width="120%" height="140%"><feGaussianBlur stdDeviation="2.4" /></filter>
        <linearGradient id={`${id}aur`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" stopColor={NIGHT.aurViolet} stopOpacity="0" />
          <stop offset="0.6" stopColor={NIGHT.aurViolet} stopOpacity="0.18" />
          <stop offset="1" stopColor={NIGHT.aurGreen} stopOpacity="0.42" />
        </linearGradient>
      </defs>
      <rect width="1600" height="1000" fill={`url(#${id}sky)`} />
      <rect width="1600" height="1000" fill={`url(#${id}glow)`} />
      {art.stars.map((st, i) => <circle key={i} cx={st.x} cy={st.y} r={st.r} fill={NIGHT.star} opacity={st.o} />)}
      {art.curtains.map((c, i) => (
        <g key={i} opacity={i ? 0.6 : 0.9}>
          <path d={c.d} fill={`url(#${id}aur)`} filter={`url(#${id}soft)`} />
          <path d={c.rays} stroke={NIGHT.aurGreen} strokeOpacity="0.3" strokeWidth="2.5" filter={`url(#${id}rays)`} />
        </g>
      ))}
      {art.ridges.map((r) => (
        <g key={r.k}>
          <path d={r.d} fill={NIGHT.groundDusk} stroke={r.index ? NIGHT.index : NIGHT.line} strokeWidth={r.index ? 1.8 : 1.2} />
          {r.k === 9 ? <path d={art.route} fill="none" stroke={NIGHT.route} strokeWidth="3" strokeDasharray="2 10" strokeLinecap="round" /> : null}
        </g>
      ))}
    </svg>
  );
}

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef } from 'react';
import {
  AdditiveBlending, BackSide, BufferAttribute, BufferGeometry, CatmullRomCurve3, Color, DoubleSide, MathUtils, MeshBasicMaterial,
  OctahedronGeometry, PlaneGeometry, Raycaster, ShaderMaterial, SphereGeometry, TubeGeometry, Vector2, Vector3,
  type PerspectiveCamera,
} from 'three';
import { spring, stepSpring } from '../../../motion';
import { CameraRig, useQuality, type CameraPose } from '../../../three';
import { NIGHT, STOP_U } from './palette';
import { SIZE, VIEWPOINTS, WATER, cameraPath, height, marchTerrain, routePoints, type StopId } from './terrain';
import { skyFrag, skyVert, starFrag, starVert, terrainFrag, terrainVert } from './shaders';

/** The page owns scroll; the scene only reads it. Written by the page's ScrollTrigger, read every frame here. */
export interface Bridge {
  /** The camera's place on its path (0–1), with rest zones already applied. */
  u: number;
  /** Scroll-speed flare request (0–1): fast scrolling briefly brightens the aurora. Decays in the scene. */
  kick: number;
  invalidate: (() => void) | null;
  /** Scene → DOM: how strongly the sky is lit (0–1.5), for the aurora tint on the caption panels' top edges. */
  light: ((lit: number) => void) | null;
  /** Scene → DOM: the camera sway (−1…1) so the layered title moves in depth with the view. */
  sway: ((x: number, y: number) => void) | null;
}

/** Hands on the scene, written by DOM listeners on the stage (the canvas itself never takes pointer events). */
export interface Input {
  /** Pointer in stage coordinates, −1…1, y up. */
  px: number;
  py: number;
  /** A fine pointer (or a touch drag) is over the stage: the head-torch and the sway follow it. */
  over: boolean;
  /** Look-around yaw from a horizontal drag, radians, already rubber-banded at the limits. */
  drag: number;
  dragging: boolean;
  /** Yaw velocity at release (rad/s): the spring back keeps it. */
  release: number;
  /** Look buttons held: −1 (left), 0, 1 (right). */
  hold: number;
  /** One-shot yaw velocity kick (rad/s) from a Look button press. */
  impulse: number;
  /** Scene → DOM: the current look yaw, so a new drag picks the view up where the spring has it (interruptible). */
  yaw: number;
}

/** ±20° of look-around; the pointer sway is ±1.5°. */
export const LOOK_MAX = MathUtils.degToRad(20);
const SWAY = MathUtils.degToRad(1.5);
const UP = new Vector3(0, 1, 0);
const PRESETS: Record<StopId, CameraPose> = Object.fromEntries(VIEWPOINTS.map((v) => [v.id, { position: v.position, target: v.target, fov: 42 }])) as Record<StopId, CameraPose>;
const color = (hex: string) => ({ value: new Color(hex) });
const smooth = (a: number, b: number, x: number): number => { const t = MathUtils.clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };

interface Mats { terrain: ShaderMaterial; sky: ShaderMaterial; stars: ShaderMaterial; route: MeshBasicMaterial; halo: MeshBasicMaterial; fells: MeshBasicMaterial }

/** The far fells: a ring of silhouettes around the map, standing just above the horizon against the afterglow. */
function fellsGeometry(): BufferGeometry {
  const n = 256;
  const R = 165;
  const pos = new Float32Array((n + 1) * 6);
  const idx: number[] = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    const p = 0.5 + 0.22 * Math.sin(3 * a + 1) + 0.14 * Math.sin(7 * a + 0.3) + 0.09 * Math.sin(13 * a + 2) + 0.05 * Math.sin(29 * a + 0.7);
    const x = Math.sin(a) * R;
    const z = -Math.cos(a) * R;
    pos.set([x, -40, z, x, 13 + p * 13, z], i * 6);
    if (i < n) { const b = i * 2; idx.push(b, b + 1, b + 2, b + 1, b + 3, b + 2); }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeBoundingSphere();
  return g;
}

/**
 * One frame loop for everything that moves: camera travel (damped toward the page's progress), the entrance push-in,
 * the look-around spring and pointer sway, the head-torch, the colour script and the aurora flare. It requests frames
 * only while something is still settling, so a paused, settled scene draws nothing.
 */
function Director({ bridge, input, mats, reduced, animate, stop }: { bridge: Bridge; input: Input; mats: Mats; reduced: boolean; animate: boolean; stop: StopId }) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const invalidate = useThree((s) => s.invalidate);
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const path = useMemo(() => cameraPath(), []);
  const tmp = useMemo(() => ({ look: new Vector3(), dir: new Vector3(), right: new Vector3(), aim: new Vector3(), ndc: new Vector2(), ray: new Raycaster() }), []);
  const pal = useMemo(() => ({
    duskTop: new Color(NIGHT.duskTop), nightTop: new Color(NIGHT.nightTop), duskHorizon: new Color(NIGHT.duskHorizon),
    nightHorizon: new Color(NIGHT.nightHorizon), groundDusk: new Color(NIGHT.groundDusk), groundNight: new Color(NIGHT.groundNight),
    floor: new Color(),
  }), []);
  const st = useRef({
    u: bridge.u,
    intro: { x: reduced ? 0 : 1, v: 0 },
    yaw: { x: 0, v: 0 },
    wasDragging: false,
    swayX: 0,
    swayY: 0,
    torchK: 0,
    torch: new Vector3(0, 3, 4),
    torchSeen: false,
    flare: 0,
    lit: -1,
    swayOut: [9, 9],
  });

  useEffect(() => { bridge.invalidate = invalidate; invalidate(); return () => { bridge.invalidate = null; }; }, [bridge, invalidate]);
  useEffect(() => {
    camera.fov = aspect < 0.8 ? 62 : aspect < 1.2 ? 50 : 42;
    camera.updateProjectionMatrix();
    invalidate();
  }, [aspect, camera, invalidate]);

  useFrame((_, rawDt) => {
    const dt = Math.min(rawDt, 1 / 20);
    const s = st.current;
    let busy = false;

    // ── Camera (scroll mode only: under reduced motion the three-kit CameraRig cuts between stops) ──
    if (!reduced) {
      const goal = MathUtils.clamp(bridge.u, 0, 1);
      s.u = MathUtils.damp(s.u, goal, 3.4, dt);
      if (Math.abs(goal - s.u) < 1e-4) s.u = goal; else busy = true;

      // Entrance: the camera settles in from higher and further back on a large, slow spring.
      stepSpring(s.intro, 0, spring.glide, dt);
      if (Math.abs(s.intro.x) + Math.abs(s.intro.v) > 1e-4) busy = true; else { s.intro.x = 0; s.intro.v = 0; }

      // Look-around: the drag drives the yaw directly; on release a spring carries the throw and brings it home.
      if (input.dragging) {
        s.yaw.x = input.drag;
        s.wasDragging = true;
      } else {
        if (s.wasDragging) { s.yaw.v = input.release; s.wasDragging = false; }
        if (input.impulse) { s.yaw.v += input.impulse; input.impulse = 0; }
        stepSpring(s.yaw, input.hold * LOOK_MAX * 0.85, spring.release, dt);
        // Rubber-band past the limit instead of a hard stop.
        if (Math.abs(s.yaw.x) > LOOK_MAX) s.yaw.x = Math.sign(s.yaw.x) * (LOOK_MAX + (Math.abs(s.yaw.x) - LOOK_MAX) * 0.5);
      }
      if (input.dragging || Math.abs(s.yaw.v) > 1e-4 || Math.abs(s.yaw.x - input.hold * LOOK_MAX * 0.85) > 1e-4) busy = true;

      // Pointer sway, ±1.5°, heavily damped: the camera is a person standing on a ridge, not a gimbal.
      const sx = input.over ? -input.px * SWAY : 0;
      const sy = input.over ? input.py * SWAY * 0.7 : 0;
      s.swayX = MathUtils.damp(s.swayX, sx, 2.2, dt);
      s.swayY = MathUtils.damp(s.swayY, sy, 2.2, dt);
      if (Math.abs(s.swayX - sx) + Math.abs(s.swayY - sy) > 1e-5) busy = true;
      input.yaw = s.yaw.x;
      const ox = s.swayX / SWAY;
      const oy = s.swayY / SWAY;
      if (Math.abs(ox - s.swayOut[0]) + Math.abs(oy - s.swayOut[1]) > 0.004) { s.swayOut = [ox, oy]; bridge.sway?.(ox, oy); }

      path.pos.getPoint(s.u, camera.position);
      path.look.getPoint(s.u, tmp.look);
      camera.position.y += 3.2 * s.intro.x;
      camera.position.z += 7 * s.intro.x;
      tmp.dir.subVectors(tmp.look, camera.position).applyAxisAngle(UP, s.yaw.x + s.swayX);
      tmp.right.crossVectors(tmp.dir, UP).normalize();
      tmp.dir.applyAxisAngle(tmp.right, s.swayY);
      camera.lookAt(tmp.look.addVectors(camera.position, tmp.dir));
    }

    // ── Head-torch: aims at the pointer's spot on the ground, with a little lag (a hand holds it) ──
    let want = 0;
    if (input.over) {
      camera.updateMatrixWorld();
      tmp.ndc.set(input.px, input.py);
      tmp.ray.setFromCamera(tmp.ndc, camera);
      if (marchTerrain(tmp.ray.ray, tmp.aim)) {
        want = 1;
        if (!s.torchSeen || s.torchK < 0.02) s.torch.copy(tmp.aim);
        s.torchSeen = true;
      }
    }
    s.torchK = MathUtils.damp(s.torchK, want, want > s.torchK ? 8 : 3, dt);
    if (want) {
      const before = s.torch.distanceToSquared(tmp.aim);
      s.torch.x = MathUtils.damp(s.torch.x, tmp.aim.x, 11, dt);
      s.torch.y = MathUtils.damp(s.torch.y, tmp.aim.y, 11, dt);
      s.torch.z = MathUtils.damp(s.torch.z, tmp.aim.z, 11, dt);
      if (before > 1e-5) busy = true;
    }
    if (Math.abs(s.torchK - want) > 0.002) busy = true;
    const tu = mats.terrain.uniforms;
    tu.uTorch.value = s.torchK;
    (tu.uTorchPos.value as Vector3).copy(camera.position).y -= 0.25;
    (tu.uTorchDir.value as Vector3).subVectors(s.torch, tu.uTorchPos.value as Vector3).normalize();

    // ── Colour script: dusk at the lake, night on the ridge, the aurora at the summit ──
    const u = reduced ? STOP_U[stop] : s.u;
    const dusk = 1 - smooth(0.3, 0.64, u);
    const night = smooth(0.24, 0.72, u);
    const aur = 0.24 + 0.76 * smooth(0.42, 0.95, u);
    s.flare = MathUtils.damp(s.flare, bridge.kick, bridge.kick > s.flare ? 9 : 1.3, dt);
    bridge.kick = Math.max(0, bridge.kick - dt * 2.4);
    if (s.flare > 0.002 || bridge.kick > 0) busy = true;
    const ku = mats.sky.uniforms;
    (ku.uTop.value as Color).lerpColors(pal.duskTop, pal.nightTop, night);
    (ku.uHorizon.value as Color).lerpColors(pal.duskHorizon, pal.nightHorizon, night);
    ku.uDusk.value = dusk;
    ku.uAur.value = aur;
    ku.uFlare.value = s.flare;
    (tu.uBase.value as Color).lerpColors(pal.groundDusk, pal.groundNight, night);
    // Distance, the far fells and the land below the horizon share one colour, so the map's edge never shows.
    pal.floor.lerpColors(tu.uBase.value as Color, ku.uHorizon.value as Color, 0.28);
    (tu.uFog.value as Color).copy(pal.floor);
    (ku.uFloor.value as Color).copy(pal.floor);
    mats.fells.color.copy(pal.floor);
    tu.uDusk.value = dusk;
    tu.uAurLight.value = aur * aur * (1 + 1.2 * s.flare);
    mats.stars.uniforms.uNight.value = night;
    mats.halo.opacity = 0.12 + 0.14 * night;

    if (animate) {
      ku.uTime.value += dt;
      mats.stars.uniforms.uTime.value += dt;
    }

    const lit = Math.min(1.5, aur * (1 + 1.4 * s.flare));
    if (Math.abs(lit - s.lit) > 0.02) { s.lit = lit; bridge.light?.(lit); }
    if (busy) invalidate();
  });
  return null;
}

export function Scene({ bridge, input, reduced, animate, stop }: { bridge: Bridge; input: Input; reduced: boolean; animate: boolean; stop: StopId }) {
  const quality = useQuality();
  const invalidate = useThree((s) => s.invalidate);
  const dpr = useThree((s) => s.viewport.dpr);
  const segs = Math.round(MathUtils.clamp(220 * quality.density, 72, 220));
  const starCount = Math.round(2600 * quality.density);

  const terrain = useMemo(() => {
    const g = new PlaneGeometry(SIZE, SIZE, segs, segs);
    g.rotateX(-Math.PI / 2);
    const p = g.attributes.position as BufferAttribute;
    for (let i = 0; i < p.count; i++) p.setY(i, height(p.getX(i), p.getZ(i)));
    p.needsUpdate = true;
    g.computeVertexNormals();
    g.computeBoundingSphere();
    return g;
  }, [segs]);
  const route = useMemo(() => {
    const pts = routePoints();
    const curve = new CatmullRomCurve3(pts);
    return {
      tube: new TubeGeometry(curve, 220, 0.042, 5, false),
      halo: new TubeGeometry(curve, 160, 0.085, 6, false),
      cairns: [pts[14], pts[72], pts[pts.length - 1]],
    };
  }, []);
  const stars = useMemo(() => {
    const g = new BufferGeometry();
    const pos = new Float32Array(starCount * 3);
    const seed = new Float32Array(starCount);
    let h = 12345;
    const rnd = () => { h = (Math.imul(h, 1664525) + 1013904223) >>> 0; return h / 4294967296; };
    for (let i = 0; i < starCount; i++) {
      const az = rnd() * Math.PI * 2;
      const el = Math.asin(0.05 + rnd() * 0.95);
      pos[i * 3] = Math.cos(el) * Math.sin(az) * 190;
      pos[i * 3 + 1] = Math.sin(el) * 190;
      pos[i * 3 + 2] = Math.cos(el) * Math.cos(az) * 190;
      seed[i] = rnd();
    }
    g.setAttribute('position', new BufferAttribute(pos, 3));
    g.setAttribute('aSeed', new BufferAttribute(seed, 1));
    return g;
  }, [starCount]);
  const skyGeo = useMemo(() => new SphereGeometry(200, 64, 32), []);
  const fellsGeo = useMemo(() => fellsGeometry(), []);
  const cairnGeo = useMemo(() => new OctahedronGeometry(0.2, 0), []);

  // Materials are created here so their uniform objects are the ones the Director writes to.
  const mats = useMemo<Mats>(() => ({
    terrain: new ShaderMaterial({
      vertexShader: terrainVert, fragmentShader: terrainFrag,
      uniforms: {
        uBase: color(NIGHT.groundDusk), uLine: color(NIGHT.line), uIndex: color(NIGHT.index), uWater: color(NIGHT.water),
        uFog: color(NIGHT.duskHorizon), uAurA: color(NIGHT.aurGreen), uGlow: color(NIGHT.afterglow), uTorchCol: color(NIGHT.torch),
        uInterval: { value: 0.5 }, uFogNear: { value: 18 }, uFogFar: { value: 78 }, uWaterLevel: { value: WATER },
        uAurLight: { value: 0 }, uDusk: { value: 1 }, uTorch: { value: 0 },
        uTorchPos: { value: new Vector3() }, uTorchDir: { value: new Vector3(0, -1, 0) },
      },
    }),
    sky: new ShaderMaterial({
      vertexShader: skyVert, fragmentShader: skyFrag, side: BackSide, depthWrite: false,
      uniforms: {
        uTop: color(NIGHT.duskTop), uHorizon: color(NIGHT.duskHorizon), uGlow: color(NIGHT.afterglow), uFloor: color(NIGHT.groundDusk),
        uAurA: color(NIGHT.aurGreen), uAurB: color(NIGHT.aurViolet), uAurC: color(NIGHT.aurRose),
        uTime: { value: 7 }, uAur: { value: 0.24 }, uFlare: { value: 0 }, uDusk: { value: 1 },
      },
    }),
    stars: new ShaderMaterial({
      vertexShader: starVert, fragmentShader: starFrag, transparent: true, depthWrite: false,
      uniforms: { uColor: color(NIGHT.star), uTime: { value: 0 }, uSize: { value: 2.6 }, uDpr: { value: 1 }, uNight: { value: 0 } },
    }),
    route: new MeshBasicMaterial({ color: new Color(NIGHT.route), toneMapped: false }),
    halo: new MeshBasicMaterial({ color: new Color(NIGHT.route), toneMapped: false, transparent: true, opacity: 0.2, blending: AdditiveBlending, depthWrite: false }),
    fells: new MeshBasicMaterial({ color: new Color(NIGHT.groundDusk), toneMapped: false, side: DoubleSide }),
  }), []);

  useEffect(() => () => { terrain.dispose(); }, [terrain]);
  useEffect(() => () => { stars.dispose(); }, [stars]);
  useEffect(() => () => {
    route.tube.dispose(); route.halo.dispose(); skyGeo.dispose(); fellsGeo.dispose(); cairnGeo.dispose();
    Object.values(mats).forEach((m) => m.dispose());
  }, [route, skyGeo, fellsGeo, cairnGeo, mats]);
  useEffect(() => { mats.stars.uniforms.uDpr.value = dpr; invalidate(); }, [dpr, mats, invalidate]);

  return (
    <>
      <mesh geometry={skyGeo} material={mats.sky} renderOrder={-1} frustumCulled={false} />
      <points geometry={stars} material={mats.stars} renderOrder={0} frustumCulled={false} />
      <mesh geometry={fellsGeo} material={mats.fells} frustumCulled={false} />
      <mesh geometry={terrain} material={mats.terrain} />
      <mesh geometry={route.halo} material={mats.halo} renderOrder={1} />
      <mesh geometry={route.tube} material={mats.route} />
      {route.cairns.map((p, i) => <mesh key={i} geometry={cairnGeo} material={mats.route} position={[p.x, p.y + 0.24, p.z]} />)}
      {reduced ? <CameraRig presets={PRESETS} preset={stop} /> : null}
      <Director bridge={bridge} input={input} mats={mats} reduced={reduced} animate={animate} stop={stop} />
    </>
  );
}

/* GLSL for Kelda Ridge. Colours arrive as uniforms from the night palette (palette.ts); the colour script (dusk →
   night → aurora) and the lights (aurora from the north sky, the walker's warm head-torch) are uniforms the scene
   damps every frame. One light direction: the sky light falls from the north and above, onto the ground and, in the
   DOM, onto the top edges of the caption panels. */

const NOISE = /* glsl */ `
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}`;

export const terrainVert = /* glsl */ `
varying float vH;
varying float vDepth;
varying vec3 vWorld;
varying vec3 vNormal;
void main() {
  vec4 world = modelMatrix * vec4(position, 1.0);
  vWorld = world.xyz;
  vH = position.y;
  vNormal = normalize(mat3(modelMatrix) * normal);
  vec4 mv = viewMatrix * world;
  vDepth = -mv.z;
  gl_Position = projectionMatrix * mv;
}`;

export const terrainFrag = /* glsl */ `
uniform vec3 uBase, uLine, uIndex, uWater, uFog, uAurA, uGlow, uTorchCol;
uniform float uInterval, uFogNear, uFogFar, uWaterLevel, uAurLight, uDusk;
uniform vec3 uTorchPos, uTorchDir;
uniform float uTorch;
varying float vH;
varying float vDepth;
varying vec3 vWorld;
varying vec3 vNormal;
float isoline(float v, float width) {
  float f = abs(fract(v - 0.5) - 0.5) / max(fwidth(v), 1e-4);
  return 1.0 - smoothstep(0.0, width, f);
}
void main() {
  vec3 n = normalize(vNormal);
  // Anti-aliased shoreline (one pixel of soft edge, whatever the mesh resolution).
  float fw = max(fwidth(vH), 1e-4);
  float water = 1.0 - smoothstep(uWaterLevel + 0.004 - fw, uWaterLevel + 0.004 + fw, vH);
  float land = 1.0 - water;
  // Sky light from the north and above: slopes that face it catch the aurora.
  float north = clamp(dot(n, normalize(vec3(0.0, 0.7, -1.0))), 0.0, 1.0);
  vec3 aurora = uAurA * uAurLight * north * north;
  // The head-torch: a cone from the walker's head toward the pointer's spot on the ground.
  vec3 L = vWorld - uTorchPos;
  float dist = max(length(L), 1e-3);
  float cone = smoothstep(0.95, 0.992, dot(L / dist, uTorchDir));
  float facing = clamp(dot(n, -L / dist), 0.0, 1.0);
  float torch = uTorch * cone * (0.3 + 0.7 * facing) / (1.0 + 0.0065 * dist * dist);

  float minor = isoline(vH / uInterval, 0.9) * land;
  float major = isoline(vH / (uInterval * 5.0), 1.5) * land;
  vec3 col = mix(uBase, uWater, water) + aurora * 0.06 * land;
  col = mix(col, uLine + aurora * 0.55, minor * 0.85);
  col = mix(col, uIndex + aurora * 0.4, major * 0.95);
  // The lake mirrors the sky: its hatch lines pick up the afterglow at dusk and the aurora at night.
  float hatch = isoline(vWorld.z * 1.4, 0.8) * water;
  vec3 sheen = mix(uLine, uGlow, uDusk * 0.4) + uAurA * uAurLight * 0.4;
  col = mix(col, sheen, hatch * 0.5);
  // Warm pool of torchlight: lifts the ground and makes the nearest contour lines glow.
  col += uTorchCol * torch * (0.2 + 1.6 * max(minor, major) + 0.5 * hatch);
  // Distance fog, plus a fade at the map's edge so the square tile dissolves into the far fells' silhouette.
  float edge = smoothstep(26.0, 31.8, max(abs(vWorld.x), abs(vWorld.z)));
  col = mix(col, uFog, max(smoothstep(uFogNear, uFogFar, vDepth), edge));
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

export const skyVert = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = normalize(position);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

export const skyFrag = /* glsl */ `
uniform vec3 uTop, uHorizon, uGlow, uAurA, uAurB, uAurC, uFloor;
uniform float uTime, uAur, uFlare, uDusk;
varying vec3 vDir;
${NOISE}

// One aurora curtain seen from below: a luminous ribbon hanging from a wandering lower edge. The ribbon folds; where it
// turns edge-on to the viewer it glows brighter (the fold factor), and fine vertical rays shimmer along it.
vec3 curtain(float az, float el, float base0, float seed, float t, float amp) {
  float w = az * 1.6 + seed;
  float f1 = 2.3, f2 = 4.6;
  float a1 = 0.3 * 0.6, a2 = 0.3 * 0.36;
  float p1 = w * f1 + t * 0.11, p2 = w * f2 - t * 0.17 + seed;
  float x = az + a1 * sin(p1) + a2 * sin(p2);
  // d(x)/d(az): where it crosses zero the ribbon turns edge-on and doubles back — a bright pleat.
  float dx = 1.0 + 1.6 * (a1 * f1 * cos(p1) + a2 * f2 * cos(p2));
  float edgeOn = clamp(0.42 / (abs(dx) + 0.12), 0.22, 2.6);
  float base = base0 + 0.055 * sin(x * 2.1 + seed * 3.0 + t * 0.07) + 0.032 * sin(x * 5.7 - seed + t * 0.1) + 0.045 * (noise(vec2(x * 3.2 + seed, t * 0.05)) - 0.5);
  float h = el - base;
  float rays = 0.6 * noise(vec2(x * 64.0 + seed * 13.0, t * 0.55)) + 0.4 * noise(vec2(x * 170.0 + seed, t * 1.05));
  rays = rays * rays * rays * 2.2;
  float rayTop = 0.14 + 0.3 * noise(vec2(x * 8.0 + seed * 2.0, t * 0.08));
  float lower = smoothstep(-0.008, 0.006, h);
  float body = 1.25 * exp(-max(h, 0.0) * 26.0) + 0.3 * exp(-max(h, 0.0) * 7.0);
  float upper = smoothstep(rayTop, 0.0, h) * (0.25 + rays);
  // Pleats brighten the whole height of the ribbon, the lower edge only a little (no hot spots where they cross).
  float strength = lower * (body * mix(1.0, edgeOn, 0.35) + 0.6 * upper * edgeOn);
  strength *= 0.25 + 1.0 * smoothstep(0.2, 0.8, noise(vec2(x * 1.4 + seed, t * 0.045)));
  vec3 c = mix(uAurA, uAurB, smoothstep(0.04, 0.34, h));
  c = mix(c, uAurC, smoothstep(1.4, 2.6, edgeOn) * (1.0 - smoothstep(0.0, 0.03, h)) * 0.35);
  return c * strength * amp;
}

void main() {
  vec3 d = normalize(vDir);
  float el = asin(clamp(d.y, -1.0, 1.0));
  float az = atan(d.x, -d.z);
  vec3 col = mix(uHorizon, uTop, smoothstep(-0.03, 0.52, d.y));
  // Afterglow on the north-west horizon at dusk; it drains away as the night comes on.
  float glow = exp(-max(el, 0.0) * 5.5) * smoothstep(2.7, 0.15, abs(az + 0.6)) * step(-0.08, el);
  col = mix(col, uGlow, glow * uDusk * 0.85);
  // Aurora across the northern half of the sky: three curtains at different heights and distances.
  float north = smoothstep(2.35, 0.65, abs(az));
  float amount = uAur * (1.0 + 1.5 * uFlare);
  float t = uTime;
  vec3 aur = curtain(az, el, 0.19, 0.0, t, 1.0)
           + curtain(az * 1.18 + 0.7, el, 0.1, 4.1, t * 0.9, 0.55)
           + curtain(az * 0.82 - 0.5, el, 0.31, 8.3, t * 1.12, 0.4);
  // A broad glow under the curtains, so the sky itself brightens when they flare.
  aur += uAurA * 0.06 * exp(-abs(el - 0.2) * 5.0);
  aur *= north * amount;
  // Soft shoulder: a flare brightens the curtains without clipping them to white.
  col += aur / (1.0 + 0.55 * max(max(aur.r, aur.g), aur.b));
  // Below the horizon the dome is distant land: the far fells' colour.
  col = mix(uFloor, col, smoothstep(-0.02, 0.005, el));
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

export const starVert = /* glsl */ `
attribute float aSeed;
uniform float uTime, uSize, uDpr, uNight;
varying float vA;
void main() {
  // Stars come out as the night deepens: the brightest first, the faint ones at full dark.
  float threshold = 0.9 - 0.9 * uNight;
  float on = smoothstep(threshold, threshold + 0.08, aSeed);
  vA = on * (0.62 + 0.38 * sin(uTime * (0.5 + aSeed * 1.7) + aSeed * 40.0));
  gl_PointSize = uSize * uDpr * (0.5 + aSeed * 1.05);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

export const starFrag = /* glsl */ `
uniform vec3 uColor;
varying float vA;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float a = smoothstep(0.5, 0.1, d) * vA;
  if (a < 0.03) discard;
  gl_FragColor = vec4(uColor, a);
  #include <colorspace_fragment>
}`;

/*
 * Kelda Ridge Night Walks — a survey print that comes alive at night. The journey is always staged at dusk → night
 * (the scene's own palette, palette.ts), whatever the gallery theme, so the aurora reads in both; the plain content
 * after it follows the theme. One light: the sky to the north and above. It tints the panels' top edges (--kr-lit,
 * written by the scene) and every shadow falls below. Type is Bricolage at two extreme weights layered in depth.
 */
.root {
  --kr-pad: clamp(16px, 4cqi, 64px);
  position: relative;
  overflow-x: clip;
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}

/* Night-stage tokens (the gallery's dark values, fixed): text over the scene is checked against the brightest sky. */
.journey {
  --kr-night: #04060c;
  --kr-ink: #f3f0e8;
  --kr-ink-muted: #b6b3a8;
  --kr-panel: rgb(7 10 18 / 0.86);
  --kr-edge: rgb(243 240 232 / 0.14);
  --kr-focus: #8ab4ff;
  --kr-signal: #ff6a3d;
  --kr-aur: #47f59b;
  --kr-lit: 0.24;
  --kr-sky-light: color-mix(in oklab, var(--kr-aur) calc(var(--kr-lit) * 38%), rgb(243 240 232 / 0.13));
  --kr-rest: 0 1px 1px rgb(0 0 0 / 0.55), 0 16px 36px -16px rgb(0 0 0 / 0.8);
  --kr-lift: 0 1px 1px rgb(0 0 0 / 0.4), 0 24px 48px -18px rgb(0 0 0 / 0.9);
  position: relative;
  background: var(--kr-night);
  color: var(--kr-ink);
  color-scheme: dark;
  touch-action: pan-y pinch-zoom;
}

.kicker, .capIdx, .capMeta, .hint, .tableCap, .viewNum, .lookLabel {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ── The journey: sticky stage behind scrolling slides ──────── */
.stage { position: sticky; top: 44px; z-index: 0; height: calc(100svh - 44px); overflow: clip; background: var(--kr-night); }
.poster { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
/* Poster → live scene: the drawing comes alive with a cross-fade once the renderer exists. */
.canvas canvas { opacity: 0; transition: opacity var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease); }
.canvas [data-live] canvas { opacity: 1; }
.scrim {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(85% 70% at 0% 0%, rgb(2 4 10 / 0.6), transparent 72%),
    linear-gradient(180deg, rgb(2 4 10 / 0.45) 0%, transparent 26%),
    linear-gradient(0deg, rgb(2 4 10 / 0.5) 0%, transparent 22%);
}
.slides { position: relative; z-index: 1; margin-top: calc(-100svh + 44px); cursor: grab; }
.journey[data-dragging] .slides { cursor: grabbing; }

.heroSlide { display: grid; align-content: start; gap: clamp(14px, 2cqi, 24px); min-height: calc(100svh - 44px); padding: clamp(28px, 5cqi, 72px) var(--kr-pad) 0; }
.kicker { color: var(--kr-ink-muted); }
.title {
  display: grid;
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(4.2rem, 0.8rem + 15.5cqi, 16.5rem);
  line-height: 0.8;
  letter-spacing: -0.055em;
  text-shadow: 0 2px 28px rgb(2 4 10 / 0.45);
}
/* Each layer sits at its own depth: the scene's sway moves the near layer most (--kr-sx/--kr-sy from the scene). */
.t1, .t2, .lede { display: block; width: fit-content; will-change: transform; cursor: auto; }
.t1 { font-weight: 300; translate: calc(var(--kr-sx, 0) * 5px) calc(var(--kr-sy, 0) * -3px); }
.t2 { padding-inline-start: 0.62em; font-weight: 700; letter-spacing: -0.06em; translate: calc(var(--kr-sx, 0) * 12px) calc(var(--kr-sy, 0) * -7px); }
.lede {
  max-width: 27ch;
  margin: 8px 0 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: clamp(1.3rem, 0.95rem + 1.4cqi, 2.1rem);
  line-height: 1.16;
  text-wrap: balance;
  text-shadow: 0 1px 18px rgb(2 4 10 / 0.6);
  translate: calc(var(--kr-sx, 0) * 3px) calc(var(--kr-sy, 0) * -2px);
}
.hint { display: flex; flex-wrap: wrap; gap: 6px; }
.hint span { padding: 6px 10px; border-radius: 999px; background: rgb(7 10 18 / 0.7); box-shadow: inset 0 1px 0 var(--kr-sky-light); color: var(--kr-ink); }
.hintDrag { color: var(--kr-ink-muted); }

.slide { display: grid; align-items: center; min-height: 120svh; padding: 0 var(--kr-pad); }
.slide[data-side='end'] { justify-items: end; }
.cap {
  display: grid;
  gap: 12px;
  width: min(100%, 27rem);
  padding: clamp(18px, 2.4cqi, 28px);
  background: var(--kr-panel);
  border: 1px solid var(--kr-edge);
  border-radius: var(--mk-radius-m, 10px);
  box-shadow: inset 0 1px 0 var(--kr-sky-light), var(--kr-rest);
