}
.capIdx { display: flex; justify-content: space-between; color: var(--kr-ink-muted); }
.capTitle { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: clamp(1.75rem, 1.1rem + 1.8cqi, 2.6rem); font-weight: 700; line-height: 1; letter-spacing: -0.035em; }
.capBody { margin: 0; font-size: 1rem; line-height: 1.55; }
.capMeta { padding-top: 10px; border-top: 1px solid var(--kr-edge); color: var(--kr-ink-muted); }

/* ── Controls: sticky to the bottom of the viewport for as long as the journey lasts ── */
.hud {
  position: sticky;
  bottom: 14px;
  z-index: 3;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: end;
  gap: 10px;
  margin-top: -76px;
  padding: 0 var(--kr-pad) 14px;
  pointer-events: none;
}
.ctl { display: flex; flex-wrap: wrap; justify-content: end; gap: 10px; }
.views, .look, .toggles {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px;
  background: var(--kr-panel);
  border: 1px solid var(--kr-edge);
  border-radius: 999px;
  box-shadow: inset 0 1px 0 var(--kr-sky-light), var(--kr-rest);
  pointer-events: auto;
  cursor: auto;
}
.view, .toggle, .lookBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--kr-ink);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  /* Release: a press-token spring (CSS linear() sampled by springToLinear) brings the key back up. */
  transition:
    translate var(--kr-release-dur, 400ms) var(--kr-release, ease),
    box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease),
    color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.lookBtn { width: 36px; padding: 0; }
.lookBtn svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.lookLabel { padding: 0 2px; color: var(--kr-ink-muted); }
.view:hover, .toggle:hover, .lookBtn:hover {
  background: rgb(243 240 232 / 0.09);
  box-shadow: inset 0 1px 0 rgb(243 240 232 / 0.14), 0 6px 14px -8px rgb(0 0 0 / 0.9);
  translate: 0 -1px;
}
.view:active, .toggle:active, .lookBtn:active {
  translate: 0 1px;
  background: rgb(0 0 0 / 0.28);
  box-shadow: inset 0 2px 4px rgb(0 0 0 / 0.55), inset 0 -1px 0 rgb(243 240 232 / 0.06);
  transition-duration: var(--mk-duration-instant, 90ms);
  transition-timing-function: var(--mk-ease-standard, ease);
}
.view[aria-current], .toggle[aria-pressed='true'] {
  background: var(--kr-ink);
  color: #0b0f17;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.6), 0 1px 1px rgb(0 0 0 / 0.6), 0 8px 18px -8px rgb(0 0 0 / 0.95);
}
.view[aria-current]:active, .toggle[aria-pressed='true']:active { box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.35); }
.view:focus-visible, .toggle:focus-visible, .lookBtn:focus-visible { outline: 2px solid var(--kr-focus); outline-offset: 2px; }
.viewNum { font-size: 0.625rem; letter-spacing: 0.06em; }
@container (max-width: 34rem) {
  .hud { flex-direction: column; align-items: flex-start; gap: 6px; margin-top: -132px; }
  .ctl { justify-content: start; gap: 6px; }
  .views, .look, .toggles { padding: 3px; }
  .view, .toggle { min-height: 32px; padding: 0 11px; }
  .lookBtn { width: 32px; min-height: 32px; }
  .viewNum { display: none; }
}

.fallback { position: absolute; inset: 0; }
.fallbackNote {
  position: absolute;
  right: var(--kr-pad);
  bottom: 96px;
  max-width: 34ch;
  margin: 0;
  padding: 10px 14px;
  background: var(--kr-panel);
  border: 1px solid var(--kr-edge);
  border-radius: var(--mk-radius-m, 10px);
  box-shadow: inset 0 1px 0 var(--kr-sky-light), var(--kr-rest);
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--kr-ink);
}

@container (max-width: 34rem) { .fallbackNote { bottom: 150px; } }
/* Without a live scene (no WebGL, lost context, 3D turned off) there is nothing to look around or pause. */
.journey:has([data-maquettekit-canvas]:is([data-status='unsupported'], [data-status='error'], [data-status='lost'], [data-status='disabled'])) :is(.look, .hintDrag, .pauseSky) { display: none; }

/* ── After the journey: plain, still content in the gallery theme ── */
.walks, .bring, .ask {
  position: relative;
  z-index: 1;
  padding: clamp(72px, 10cqi, 160px) var(--kr-pad);
  border-top: 1px solid var(--mk-line, #11110f24);
  background: var(--mk-bg, #f3f0e8);
}
/* The page slides over the night stage like a sheet: its shadow falls back onto the scene. */
.walks { display: grid; gap: 28px; box-shadow: 0 -28px 60px -24px rgb(0 0 0 / 0.65); }
.walks .kicker { color: var(--mk-ink-muted, #5c5a52); }
.walksTitle h2, .placeholder, .h2, .askTitle {
  max-width: 13ch;
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
