  font-weight: 300;
  line-height: 0.92;
  letter-spacing: -0.045em;
  color: var(--mk-ink, #11110f);
}
.placeholder { opacity: 0; }
.table { width: 100%; max-width: 60rem; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.tableCap { padding-bottom: 12px; caption-side: top; text-align: start; color: var(--mk-ink-muted, #5c5a52); }
.table th, .table td { padding: 14px 12px 14px 0; border-bottom: 1px solid var(--mk-line, #11110f24); font-size: 1rem; font-weight: 400; text-align: start; }
.table thead th { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.table tbody th { font-weight: 600; }
@container (max-width: 30rem) { .table th, .table td { padding-right: 8px; font-size: 0.875rem; } }

.bring { display: grid; gap: 32px; }
@container (min-width: 56rem) { .bring { grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr); align-items: start; } }
.h2 { font-size: clamp(2.2rem, 1rem + 4cqi, 5rem); }
.bringList { display: grid; gap: 0; margin: 0; padding: 0; list-style: none; counter-reset: bring; border-top: 1px solid var(--mk-line, #11110f24); }
.bringList li { display: grid; grid-template-columns: 3rem minmax(0, 1fr); gap: 12px; padding: 16px 0; border-bottom: 1px solid var(--mk-line, #11110f24); font-size: 1.0625rem; line-height: 1.5; counter-increment: bring; }
.bringList li::before { content: counter(bring, decimal-leading-zero); font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; padding-top: 0.3em; color: var(--mk-signal, #bf2f09); }

.ask { display: grid; gap: 24px; justify-items: start; }
.askTitle { font-size: clamp(2.4rem, 1rem + 5cqi, 6rem); }
/* Primary action with real depth: a contact shadow and a soft one; hover lifts, press sinks, release springs back. */
.cta {
  display: inline-flex;
  align-items: center;
  min-height: 52px;
  padding: 0 28px;
  border-radius: 999px;
  background: var(--mk-ink, #11110f);
  color: var(--mk-bg, #f3f0e8);
  font-weight: 600;
  text-decoration: none;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.16), 0 1px 1px rgb(17 17 15 / 0.3), 0 12px 24px -12px rgb(17 17 15 / 0.55);
